ys=[0,0,0,3,11,26,17,7,1,0,0]  # so100 f300 speed400

def interp(x):
    if x <= xs[0] or x >= xs[-1]: return 0.0
    for i in range(len(xs)-1):
        if xs[i] <= x <= xs[i+1]:
            t=(x-xs[i])/(xs[i+1]-xs[i])
            return ys[i]*(1-t)+ys[i+1]*t
    return 0.0

def recipe(pitch,margin):
    centers=[]
    y=-margin + pitch/2
    while y < 300+margin:
        centers.append(y)
        y += pitch
    adds=[]
    for qy in [30,30,270,270,150]:
        adds.append(sum(interp(qy-c) for c in centers))
    n=len(centers); length=400+2*margin
    paint=300/60*n*length/400
    return adds,paint

